css:
.ds-dossier { --ds-cover-bg: var(--ds-paper); --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-violet); --ds-hand-fill2: var(--ds-ink); --ds-hand-muted: var(--ds-paper-sunk); --ds-hand-ground: var(--ds-paper-raised); --ds-hand-stroke: 2; --ds-hand-cap: square; --ds-hand-tex: 2; --ds-hand-bg: var(--ds-paper);
  --ds-tpl-edge: 1.5px solid var(--ds-ink); --ds-tpl-radius: 0; --ds-tpl-rule: 3px solid var(--ds-ink); --ds-tag-radius: 2px; --ds-slide-bg: var(--ds-paper-raised); --ds-slide-title-bg: var(--ds-night); --ds-slide-title-fg: var(--ds-on-night); --ds-slide-split-a: var(--ds-violet); --ds-slide-split-a-fg: var(--ds-on-violet); --ds-slide-split-b: var(--ds-ink); --ds-slide-split-b-fg: var(--ds-paper); }
.ds-dossier .ds-section h2 { font-family: var(--font-display); }
.ds-dossier .ds-chip { border-width: 1.5px; border-color: var(--ds-ink); font-family: var(--font-mono); font-weight: 700; }
.ds-dossier .ds-section { border-top-width: 3px; border-top-color: var(--ds-ink); }
.ds-dossier .ds-principle-n { font-family: var(--font-mono); font-size: 18px; font-weight: 700; background: var(--ds-ink); color: var(--ds-paper); width: 44px; height: 44px; display: inline-flex; align-items: center; justify-content: center; }
.ds-dossier .ds-tpl-brand, .ds-dossier .ds-tpl-slide-h, .ds-dossier .ds-tpl-hero-h, .ds-dossier .ds-tpl-ed-h, .ds-dossier .ds-tpl-dropcap { text-transform: uppercase; font-stretch: 62%; font-weight: 900; }
.ds-dossier .ds-tpl-slide-big, .ds-dossier .ds-tpl-pull-n, .ds-dossier .h-num { font-stretch: 75%; font-weight: 800; }
.ds-dossier .ds-tpl-step h4, .ds-dossier .ds-tpl-feat h4, .ds-dossier .ds-tpl-head h3 { text-transform: uppercase; font-stretch: 80%; }
.ds-dossier .ds-tpl-tag { font-family: var(--font-mono); border: 1.5px solid currentColor; }
.ds-dossier .ds-tpl-tag.is-idle { border-style: dashed; background: transparent; }
.ds-dossier .ds-tpl-stage-top, .ds-dossier .ds-tpl-stage-foot { font-weight: 700; }
.ds-dossier .ds-tpl-ed-body { font-family: var(--font-body); }
.ds-dossier .ds-tpl-row-name { font-family: var(--font-display); font-stretch: 80%; text-transform: uppercase; }
.ds-dossier .ds-comp, .ds-dossier .ds-note, .ds-dossier .ds-voice, .ds-dossier .ds-motif, .ds-dossier .ds-hand-panel { border-color: var(--ds-ink); border-width: 1.5px; }
/* svg vocabulary */
.ds-dossier .do-paper { fill: var(--ds-paper); } .ds-dossier .do-ink, .ds-dossier .do-fillink { fill: var(--ds-hand-ink); } .ds-dossier .do-night { fill: var(--ds-night); } .ds-dossier .do-lime { fill: var(--ds-lime); }
.ds-dossier .do-hatch line { stroke: var(--ds-hand-fill); stroke-width: 2; } .ds-dossier .do-violet-rim { fill: none; stroke: var(--ds-hand-ink); stroke-width: 2; }
.ds-dossier .do-stamp-rim { fill: none; stroke: var(--ds-hand-fill); stroke-width: 3; } .ds-dossier .do-stamp-rim-thin { fill: none; stroke: var(--ds-hand-fill); stroke-width: 1.5; }
.ds-dossier .do-svg-mono { font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .14em; fill: var(--ds-hand-ink); } .ds-dossier .do-svg-soft { fill: var(--ds-ink-soft); } .ds-dossier .do-on-night { fill: var(--ds-on-night); } .ds-dossier .do-on-hatch { fill: var(--ds-hand-ink); }
.ds-dossier .do-svg-numblock { font-family: var(--font-mono); font-size: 22px; font-weight: 700; fill: var(--ds-paper); } .ds-dossier .do-on-ink { fill: var(--ds-paper); }
.ds-dossier .do-svg-head { font-family: var(--font-display); font-weight: 900; font-stretch: 62%; font-size: 56px; letter-spacing: -.01em; fill: var(--ds-hand-ink); }
.ds-dossier .do-svg-head-l { font-family: var(--font-display); font-weight: 900; font-stretch: 62%; font-size: 48px; letter-spacing: -.01em; fill: var(--ds-hand-ink); }
.ds-dossier .do-svg-stamp { font-family: var(--font-mono); font-size: 16px; font-weight: 700; letter-spacing: .16em; fill: var(--ds-hand-fill); }
.ds-dossier .do-svg-tag { fill: none; stroke: var(--ds-hand-ink); stroke-width: 1.5; } .ds-dossier .do-svg-tag-intel { stroke-dasharray: 4 3; }
.ds-dossier .do-svg-tagtext { font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .14em; fill: var(--ds-hand-ink); }
.ds-dossier .do-svg-body { font-family: var(--font-body); font-size: 17px; fill: var(--ds-hand-ink); }
/* authored components */
.ds-dossier .do-btn { font-family: var(--font-mono); font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; line-height: 16px; padding: 11px 16px; border: 1.5px solid var(--ds-ink); border-radius: 2px; background: transparent; color: var(--ds-ink); cursor: pointer; transition: background 120ms linear, color 120ms linear; }
.ds-dossier .do-btn:hover { background: var(--ds-ink); color: var(--ds-paper); }
.ds-dossier .do-btn:focus-visible { outline: 3px solid var(--ds-violet); outline-offset: 2px; }
.ds-dossier .do-btn-primary { background: var(--ds-violet); border-color: var(--ds-violet); color: var(--ds-on-violet); } .ds-dossier .do-btn-primary:hover { background: var(--ds-ink); border-color: var(--ds-ink); color: var(--ds-paper); }
.ds-dossier .do-btn-lime { background: var(--ds-lime); border-color: var(--ds-ink); color: var(--ds-on-lime); }
.ds-dossier .do-tag { display: inline-flex; align-items: center; gap: 6px; font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; line-height: 1.2; padding: 3px 7px; border: 1.5px solid currentColor; border-radius: 2px; white-space: nowrap; color: var(--ds-ink); }
.ds-dossier .do-tag-intel { border-style: dashed; } .ds-dossier .do-tag-plan { background: var(--ds-ink); color: var(--ds-paper); } .ds-dossier .do-tag-verified { border-width: 3px; border-style: double; }
.ds-dossier .do-tag-lime { background: var(--ds-lime); color: var(--ds-on-lime); border-color: var(--ds-ink); }
.ds-dossier .do-tag-status.is-ok { background: var(--ds-positive-soft); color: var(--ds-positive); } .ds-dossier .do-tag-status.is-warn { background: var(--ds-caution-soft); color: var(--ds-caution); } .ds-dossier .do-tag-status.is-bad { background: var(--ds-negative-soft); color: var(--ds-negative); }
.ds-dossier .do-hl { font-style: normal; position: relative; display: inline-block; isolation: isolate; }
.ds-dossier .do-hl::after { content: ""; position: absolute; left: -.04em; right: -.04em; bottom: .04em; height: .22em; background: var(--ds-lime); z-index: -1; transform: skewX(-8deg); }
.ds-dossier .do-redact { display: inline-block; background: currentColor; height: .95em; vertical-align: -.12em; border-radius: 1px; }
.ds-dossier .do-stamp { display: inline-block; font-family: var(--font-mono); font-weight: 700; font-size: 13px; letter-spacing: .16em; text-transform: uppercase; color: var(--ds-violet); border: 3px solid currentColor; border-radius: 3px; padding: 6px 10px; line-height: 1.15; transform: rotate(-6deg); outline: 1.5px solid currentColor; outline-offset: 3px; }
.ds-dossier .do-fact { display: grid; gap: 4px; padding: 14px 16px 14px 0; border-top: 3px solid var(--ds-ink); min-width: 150px; } .ds-dossier .do-fact-accent .t-numeral { color: var(--ds-violet); }
.ds-dossier .do-callout { display: grid; gap: 8px; justify-items: start; padding: 14px 16px; border: 1.5px solid var(--ds-ink); font-family: var(--font-body); font-size: 17px; line-height: 1.45; } .ds-dossier .do-callout p { margin: 0; }
.ds-dossier .do-callout-intel { background: var(--ds-caution-soft); } .ds-dossier .do-callout-ok { background: var(--ds-positive-soft); } .ds-dossier .do-callout-bad { background: var(--ds-negative-soft); }
.ds-dossier .do-file { position: relative; background: var(--ds-paper-raised); color: var(--ds-ink); padding: 22px 22px 20px; border: 1.5px solid var(--ds-ink); box-shadow: var(--ds-shadow-file); margin: 26px 0 30px; max-width: 420px; }
.ds-dossier .do-file-tab { position: absolute; top: -26px; left: -1.5px; background: var(--ds-ink); color: var(--ds-paper); font-family: var(--font-mono); font-weight: 700; font-size: 11px; letter-spacing: .2em; text-transform: uppercase; padding: 6px 14px 5px; clip-path: polygon(0 0, 86% 0, 100% 100%, 0 100%); }
.ds-dossier .do-file-dl { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 0 14px; }
.ds-dossier .do-file-dl dt, .ds-dossier .do-file-dl dd { margin: 0; padding: 8px 0; border-bottom: 1px solid var(--ds-line); font-size: 14px; }
.ds-dossier .do-file-dl dt { font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--ds-ink-soft); padding-top: 10px; }
.ds-dossier .do-file-dl dd { font-weight: 600; font-family: var(--font-display); font-stretch: 90%; }
.ds-dossier .do-file .do-stamp { position: absolute; right: 14px; bottom: -22px; background: var(--ds-paper-raised); }
/* sample */
.ds-dossier .do-sample { background: var(--ds-paper); color: var(--ds-ink); }
.ds-dossier .do-sample-in { max-width: 1180px; margin: 0 auto; padding: 0 20px; }
.ds-dossier .do-mast { display: flex; justify-content: space-between; gap: 16px; padding: 14px 20px 10px; border-bottom: 3px solid var(--ds-ink); font-family: var(--font-mono); font-size: 11px; font-weight: 500; letter-spacing: .14em; text-transform: uppercase; } .ds-dossier .do-mast b { font-weight: 700; } .ds-dossier .do-mast-mid { display: none; }
.ds-dossier .do-kicker { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 32px 0 0; font-family: var(--font-mono); font-size: 12px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; }
.ds-dossier .do-h1 { margin: 12px 0 0; } .ds-dossier .do-l1, .ds-dossier .do-l2 { display: block; } .ds-dossier .do-l2 { color: var(--ds-violet); }
.ds-dossier .do-hero-grid { display: grid; gap: 28px; margin-top: 32px; padding-bottom: 56px; align-items: start; }
.ds-dossier .do-dek { margin: 0; }
.ds-dossier .do-facts { list-style: none; margin: 0; padding: 0; border-top: 3px solid var(--ds-ink); }
.ds-dossier .do-facts li { display: grid; grid-template-columns: auto 1fr; gap: 4px 16px; align-items: baseline; border-bottom: 1px solid var(--ds-ink); padding: 8px 0; }
.ds-dossier .do-facts-n { font-family: var(--font-display); font-weight: 800; font-stretch: 75%; font-size: 40px; line-height: .95; letter-spacing: -.01em; font-variant-numeric: tabular-nums; } .ds-dossier .do-facts-violet { color: var(--ds-violet); }
.ds-dossier .do-facts .t-label { color: var(--ds-ink-soft); text-align: right; }
.ds-dossier .do-night-sec { background: var(--ds-night); color: var(--ds-on-night); padding: 56px 0 64px; }
.ds-dossier .do-shead { display: grid; grid-template-columns: auto 1fr; gap: 0 20px; align-items: end; border-bottom: 3px solid currentColor; padding-bottom: 14px; }
.ds-dossier .do-shead-n { font-family: var(--font-mono); font-weight: 700; font-size: 14px; letter-spacing: .12em; padding: 6px 8px; background: var(--ds-lime); color: var(--ds-on-lime); align-self: start; margin-top: .4em; }
.ds-dossier .do-shead h3 { margin: 0; } .ds-dossier .do-shead-k { grid-column: 1 / -1; margin: 14px 0 0; display: flex; flex-wrap: wrap; gap: 6px 18px; color: var(--ds-night-muted); }
.ds-dossier .do-night-grid { display: grid; gap: 24px; margin-top: 32px; }
.ds-dossier .do-panel { background: var(--ds-paper-raised); color: var(--ds-ink); border: 2px solid var(--ds-on-night); padding: 18px; min-width: 0; } .ds-dossier .do-panel .t-label { display: block; margin-bottom: 12px; color: var(--ds-ink-soft); }
@container (min-width: 760px) { .ds-dossier .do-mast { padding: 14px 40px 10px; } .ds-dossier .do-mast-mid { display: block; } .ds-dossier .do-sample-in { padding: 0 40px; } .ds-dossier .do-hero-grid { grid-template-columns: 5fr 4fr 3fr; gap: 32px; } .ds-dossier .do-file { margin-top: 26px; } .ds-dossier .do-night-grid { grid-template-columns: 3fr 2fr; } .ds-dossier .do-night-sec { padding: 80px 0 96px; } }
